package vn.rtr.aeris.native95;
import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;
/** Bounded append-only native picker outcomes. Never contains authority or provider credentials. */
public final class FileOps87 {
 public static final int MAX_OPS=32;private final Path root;private final Map<String,DraftStore> stores=new LinkedHashMap<>();
 public static final class Op {public final String id,kind,workspace,head,phase,sha,staged,artifactHead,reason;Op(String...v){id=v[0];kind=v[1];workspace=v[2];head=v[3];phase=v[4];sha=v[5];staged=v[6];artifactHead=v[7];reason=v[8];}public String[] fields(){return new String[]{id,kind,workspace,head,phase,sha,staged,artifactHead,reason};}}
 public FileOps87(Path p)throws IOException{root=p;if(Files.isSymbolicLink(p))throw new IOException("FileOps symlink");Files.createDirectories(p);try(DirectoryStream<Path>d=Files.newDirectoryStream(p)){for(Path f:d){if(Files.isSymbolicLink(f)||!Files.isDirectory(f)||!uuid(f.getFileName().toString()))throw new IOException("FileOps entry");if(stores.size()>=MAX_OPS)throw new IOException("FileOps quota retained");DraftStore s=new DraftStore(f);Op o=decode(s.load());if(!o.id.equals(f.getFileName().toString()))throw new IOException("FileOps id mismatch");stores.put(o.id,s);}}}
 static boolean uuid(String s){return s.matches("[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}");}static boolean digest(String s){return s.matches("[a-f0-9]{64}");}
 private static byte[] encode(Op o)throws IOException{String[] v=o.fields();if(!uuid(o.id)||!Arrays.asList("export","import").contains(o.kind)||!o.workspace.matches("initial|w-[a-f0-9-]{36}")||!(o.head.equals("ROOT")||digest(o.head))||!Arrays.asList("PICKER_PENDING","PROCESSING","COMPLETED","CANCELLED","UNKNOWN").contains(o.phase)||!(o.sha.isEmpty()||digest(o.sha))||!(o.staged.isEmpty()||o.staged.matches("w-[a-f0-9-]{36}"))||!(o.artifactHead.isEmpty()||digest(o.artifactHead))||o.reason.length()>256)throw new IOException("FileOps schema");if(o.phase.equals("COMPLETED")&&(!digest(o.sha)||!digest(o.artifactHead)||o.kind.equals("import")&&o.staged.isEmpty()))throw new IOException("FileOps incomplete completion");StringBuilder b=new StringBuilder("AERISFILEOP87\n");for(String x:v)b.append(Base64.getEncoder().encodeToString(x.getBytes(StandardCharsets.UTF_8))).append('\n');return b.toString().getBytes(StandardCharsets.US_ASCII);}
 private static Op decode(DraftStore.Snapshot s)throws IOException{if(s==null||s.bytes.length>4096)throw new IOException("FileOps missing/bound");String[] rows=new String(s.bytes,StandardCharsets.US_ASCII).split("\n",-1);if(rows.length!=11||!rows[0].equals("AERISFILEOP87")||!rows[10].isEmpty())throw new IOException("FileOps envelope");String[]v=new String[9];try{for(int i=0;i<9;i++)v[i]=new String(Base64.getDecoder().decode(rows[i+1]),StandardCharsets.UTF_8);}catch(Exception e){throw new IOException("FileOps encoding");}Op o=new Op(v);if(!Arrays.equals(encode(o),s.bytes))throw new IOException("FileOps canonical");return o;}
 public synchronized Op begin(String id,String kind,String workspace,String head,String sha)throws IOException{if(stores.containsKey(id)||stores.size()>=MAX_OPS)throw new IOException("FileOps duplicate/quota; no retry");Op o=new Op(id,kind,workspace,head,"PICKER_PENDING",sha,"","","");byte[]b=encode(o);DraftStore s=new DraftStore(root.resolve(id));s.save("ROOT",b);stores.put(id,s);return o;}
 public synchronized Op get(String id)throws IOException{DraftStore s=stores.get(id);if(s==null)throw new IOException("Unknown original operation");return decode(s.load());}
 public synchronized Op update(String id,String phase,String sha,String staged,String artifactHead,String reason)throws IOException{Op o=get(id);if(phase.equals("COMPLETED")&&!Arrays.asList("PROCESSING","UNKNOWN","COMPLETED").contains(o.phase))throw new IOException("FileOps processing evidence required");if(Arrays.asList("COMPLETED","CANCELLED").contains(o.phase)&&!phase.equals(o.phase))throw new IOException("FileOps terminal retained");if(!o.sha.isEmpty()&&!sha.equals(o.sha)||!o.staged.isEmpty()&&!staged.equals(o.staged)||!o.artifactHead.isEmpty()&&!artifactHead.equals(o.artifactHead))throw new IOException("FileOps bound identity mismatch");Op n=new Op(id,o.kind,o.workspace,o.head,phase,sha,staged,artifactHead,reason);DraftStore s=stores.get(id);s.save(s.load().token,encode(n));return n;}
 public synchronized List<Op> list()throws IOException{List<Op> out=new ArrayList<>();for(String id:stores.keySet())out.add(get(id));return out;}
 public synchronized void recover()throws IOException{for(Op o:list())if(o.phase.equals("PICKER_PENDING")||o.phase.equals("PROCESSING"))update(o.id,"UNKNOWN",o.sha,o.staged,o.artifactHead,"PROCESS_RESTART_OUTCOME_UNCONFIRMED_NO_RETRY");}
}
